import 'package:test/test.dart';

const podspecPath = 'vendor/wasm_run_flutter/macos/wasm_run_flutter.podspec';
const classesDir = 'vendor/wasm_run_flutter/macos/Classes';
const podfilePath = 'flutter_app/macos/Podfile';

